-- ============================================================
-- Parklea SFC - editable page copy + FAQs
-- Run once in the Supabase SQL Editor (Dashboard, SQL Editor).
-- Non-destructive and safe to re-run.
--
-- The seeded text is base64 so this file contains no quotes,
-- semicolons, line breaks or accents inside any string. Postgres
-- decodes it on insert, so the stored content is exactly the
-- wording already on the website.
-- ============================================================

-- ---------- STEP 1 of 3: tables ----------

create table if not exists public.faqs (
  id         uuid primary key default gen_random_uuid(),
  question   text not null,
  answer     text not null,
  sort_order int not null default 0,
  created_at timestamptz not null default now()
);

create table if not exists public.page_content (
  id         uuid primary key default gen_random_uuid(),
  page       text not null,
  key        text not null,
  value      text not null default '',
  created_at timestamptz not null default now(),
  unique (page, key)
);

alter table public.faqs         enable row level security;
alter table public.page_content enable row level security;

drop policy if exists "Public read"  on public.faqs;
drop policy if exists "Admin insert" on public.faqs;
drop policy if exists "Admin update" on public.faqs;
drop policy if exists "Admin delete" on public.faqs;
create policy "Public read"  on public.faqs for select using (true);
create policy "Admin insert" on public.faqs for insert to authenticated with check (true);
create policy "Admin update" on public.faqs for update to authenticated using (true);
create policy "Admin delete" on public.faqs for delete to authenticated using (true);

drop policy if exists "Public read"  on public.page_content;
drop policy if exists "Admin insert" on public.page_content;
drop policy if exists "Admin update" on public.page_content;
drop policy if exists "Admin delete" on public.page_content;
create policy "Public read"  on public.page_content for select using (true);
create policy "Admin insert" on public.page_content for insert to authenticated with check (true);
create policy "Admin update" on public.page_content for update to authenticated using (true);
create policy "Admin delete" on public.page_content for delete to authenticated using (true);

-- ---------- STEP 2 of 3: page copy ----------

on conflict (page, key) do nothing;

